#include <iostream>
#include <type_traits>
template <typename T, typename U>
constexpr bool is_same_v = std::is_same_v<T, U>;
template <int N>
constexpr int powerOfTwo() {
  if constexpr (N == 0) {
    return 1;
  } else {
    return 2 * powerOfTwo<N - 1>();
  }
}
int main() {
  constexpr int result = powerOfTwo<10>();
  std::cout << "2 to the power of 10 (compile time): " << result << std::endl;
  if constexpr (is_same_v<int, int>) {
      std::cout << "int is same as int (compile time check)" << std::endl;
  }
  return 0;
}
